<!doctype html><html lang="es"><head><meta charset="utf-8"><title>{{ $voucher->consecutive }}</title><style>body{font-family:Arial;padding:30px;color:#222}table{width:100%;border-collapse:collapse}th,td{border:1px solid #ddd;padding:8px;text-align:left}@media print{.actions{display:none}}</style></head><body><div class="actions"><button onclick="print()">Imprimir</button><button onclick="download()">Descargar</button></div><h1>Estado de cuenta / comprobante</h1><p><b>Tipo:</b> {{ $voucher->voucher_type }}</p><p><b>Consecutivo:</b> {{ $voucher->consecutive }} | <b>Fecha:</b> {{ $voucher->voucher_date }}</p><p><b>Tercero:</b> {{ $voucher->third_party }}</p><p>{{ $voucher->description }}</p><table><thead><tr><th>Cuenta</th><th>Detalle</th><th>Débito</th><th>Crédito</th></tr></thead><tbody>@foreach($voucher->lines as $line)<tr><td>{{ $line->account->code }} - {{ $line->account->name }}</td><td>{{ $line->detail }}</td><td>{{ number_format($line->debit, 2) }}</td><td>{{ number_format($line->credit, 2) }}</td></tr>@endforeach</tbody></table><h3>Total: ${{ number_format($voucher->total_debit, 2) }}</h3><script>function download(){const a=document.createElement('a');a.href='data:text/html;charset=utf-8,'+encodeURIComponent(document.documentElement.outerHTML);a.download='{{ $voucher->consecutive }}.html';a.click()}if(new URLSearchParams(location.search).get('download'))download();</script></body></html>
